void PreOrderTraverse_Iterative(BiTree T) {
    if (!T) return;

    Stack S;
    InitStack(S);
    Push(S, T);

    while (!IsEmpty(S)) {
        BiTree p = Pop(S);
        Visit(p->data);

        if (p->rchild) Push(S, p->rchild); // 右子树先入栈
        if (p->lchild) Push(S, p->lchild); // 左子树后入栈
    }
}
