void InOrderTraverse_Iterative(BiTree T) {
    Stack S;
    InitStack(S);
    BiTree p = T;

    while (p || !IsEmpty(S)) {
        if (p) {
            Push(S, p);
            p = p->lchild;  // 一直向左走
        } else {
            p = Pop(S);
            Visit(p->data);  // 访问节点
            p = p->rchild;   // 转向右子树
        }
